@page "/category/{Slug}"

<PageTitle>@CategoryName - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1>@CategoryName</h1>

    @if (Recipes.Any())
    {
        <div class="row">
            @foreach (var recipe in Recipes)
            {
                <div class="col-md-6 mb-3">
                    <div class="card">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text">@recipe.Summary</p>
                            <a href="/recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
    else
    {
        <p class="text-muted">No recipes found in this category yet.</p>
    }
</div>

@code {
    [Parameter]
    public string Slug { get; set; } = "";

    private string CategoryName => Slug switch
    {
        "appetizers" => "🥗 Appetizers",
        "main-courses" => "🍝 Main Courses",
        "desserts" => "🍰 Desserts",
        _ => "Recipes"
    };

    private List<RecipeInfo> Recipes => Slug switch
    {
        "appetizers" => new()
        {
            new("bruschetta", "Classic Bruschetta", "Toasted bread topped with fresh tomatoes, basil, and garlic."),
            new("spring-rolls", "Vegetable Spring Rolls", "Crispy rolls filled with fresh vegetables and served with dipping sauce.")
        },
        "main-courses" => new()
        {
            new("spaghetti-carbonara", "Spaghetti Carbonara", "Creamy Italian pasta with pancetta, egg, and parmesan."),
            new("chicken-tikka", "Chicken Tikka Masala", "Tender chicken in a rich, spiced tomato-cream sauce.")
        },
        "desserts" => new()
        {
            new("tiramisu", "Tiramisu", "Classic Italian dessert with layers of coffee-soaked ladyfingers and mascarpone cream."),
            new("chocolate-cake", "Chocolate Lava Cake", "Rich chocolate cake with a molten center.")
        },
        _ => new()
    };

    private record RecipeInfo(string Id, string Title, string Summary);
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<div class="container">
    <h1>📝 Submit Your Recipe</h1>
    <p>Share your favorite recipe with the community!</p>

    @if (submitted)
    {
        <div class="alert alert-success">
            <h4>🎉 Recipe Submitted!</h4>
            <p>Thank you for sharing "<strong>@Model.Title</strong>" with the community.</p>
            <a href="/" class="btn btn-primary">Back to Home</a>
        </div>
    }
    else
    {
        <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" @bind-Value="Model.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
                <ValidationMessage For="() => Model.Title" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" @bind-Value="Model.Category" class="form-select">
                    <option value="">-- Select a category --</option>
                    <option value="appetizers">Appetizers</option>
                    <option value="main-courses">Main Courses</option>
                    <option value="desserts">Desserts</option>
                </InputSelect>
                <ValidationMessage For="() => Model.Category" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients (one per line)</label>
                <InputTextArea id="ingredients" @bind-Value="Model.Ingredients" class="form-control" rows="6"
                    placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
                <ValidationMessage For="() => Model.Ingredients" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps (one per line)</label>
                <InputTextArea id="steps" @bind-Value="Model.Steps" class="form-control" rows="6"
                    placeholder="Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
                <ValidationMessage For="() => Model.Steps" class="text-danger" />
            </div>

            <button type="submit" class="btn btn-success btn-lg">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    private RecipeSubmission Model { get; set; } = new();
    private bool submitted;

    private void HandleSubmit()
    {
        submitted = true;
    }

    public class RecipeSubmission
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please enter a recipe title.")]
        [System.ComponentModel.DataAnnotations.StringLength(100, MinimumLength = 3)]
        public string Title { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please list the ingredients.")]
        public string Ingredients { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please describe the steps.")]
        public string Steps { get; set; } = "";
    }
}

@rendermode InteractiveServer

<div class="star-rating">
    <span class="me-2">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= currentRating ? "filled" : "")"
              @onclick="() => SetRating(star)"
              @onmouseover="() => hoverRating = star"
              @onmouseout="() => hoverRating = 0"
              style="cursor: pointer; font-size: 1.5rem;"
              title="@star star(s)">
            @(star <= (hoverRating > 0 ? hoverRating : currentRating) ? "★" : "☆")
        </span>
    }
    @if (currentRating > 0)
    {
        <span class="ms-2 text-muted">You rated this @currentRating/5</span>
    }
</div>

@code {
    [Parameter]
    public string RecipeId { get; set; } = "";

    private int currentRating;
    private int hoverRating;

    private void SetRating(int rating)
    {
        currentRating = rating;
    }
}

.star-rating {
    display: inline-flex;
    align-items: center;
}

.star {
    transition: color 0.15s;
    color: #ccc;
}

.star.filled,
.star:hover {
    color: #ffc107;
}

